    "res_sw_mara.1": { en: "Hello! I'm Mara, Moritz's sister. I cut peat.", t: [["Hallo", "", "hello"], ["!", "", ""], ["Ich", "", "I", "ich"], ["bin", "", "am", "sein"], ["Mara", "", "Mara (name)"], [",", "", ""], ["die", "", "the", "der"], ["Schwester", "", "sister"], ["von", "", "of"], ["Moritz", "", "Moritz (name)"], [".", "", ""], ["Ich", "", "I", "ich"], ["steche", "", "cut", "stechen"], ["Torf", "", "peat"], [".", "", ""]] },
    "res_sw_mara.2": { en: "Peat is old moss. It grows only one millimetre a year. Dried, it burns in the stove.", t: [["Torf", "", "peat"], ["ist", "", "is", "sein"], ["altes", "", "old", "alt"], ["Moos", "", "moss"], [".", "", ""], ["Er", "", "it", "er"], ["wächst", "", "grows", "wachsen"], ["nur", "", "only"], ["einen", "", "one", "ein"], ["Millimeter", "", "millimetre"], ["im", "", "in the", "in"], ["Jahr", "", "year"], [".", "", ""], ["Getrocknet", "", "dried", "trocknen"], ["brennt", "", "burns", "brennen"], ["er", "", "it"], ["im", "", "in the", "in"], ["Ofen", "", "stove"], [".", "", ""]] },
    "res_sw_mara.3": { en: "One metre of peat is a thousand years old! That's why I only take a little.", t: [["Ein", "", "one", "ein"], ["Meter", "", "metre"], ["Torf", "", "peat"], ["ist", "", "is", "sein"], ["tausend", "", "a thousand"], ["Jahre", "", "years", "Jahr"], ["alt", "", "old"], ["!", "", ""], ["Darum", "", "that's why"], ["nehme", "", "take", "nehmen"], ["ich", "", "I"], ["nur", "", "only"], ["wenig", "", "a little"], [".", "", ""]] },
    "res_sw_hanne.1": { en: "Welcome! I'm Hanne. I collect herbs in the bog.", t: [["Willkommen", "", "welcome", "willkommen"], ["!", "", ""], ["Ich", "", "I", "ich"], ["bin", "", "am", "sein"], ["Hanne", "", "Hanne (name)"], [".", "", ""], ["Ich", "", "I", "ich"], ["sammle", "", "collect", "sammeln"], ["Kräuter", "", "herbs", "Kraut"], ["im", "", "in the", "in"], ["Moor", "", "bog"], [".", "", ""]] },
    "res_sw_hanne.2": { en: "The soil in the bog is very poor. That's why some plants eat insects, for example the sundew!", t: [["Im", "", "in the", "in"], ["Moor", "", "bog"], ["ist", "", "is", "sein"], ["der", "", "the"], ["Boden", "", "soil; ground"], ["sehr", "", "very"], ["arm", "", "poor"], [".", "", ""], ["Darum", "", "that's why"], ["fressen", "", "eat"], ["manche", "", "some", "mancher"], ["Pflanzen", "", "plants", "Pflanze"], ["Insekten", "", "insects", "Insekt"], [",", "", ""], ["zum Beispiel", "", "for example"], ["der", "", "the"], ["Sonnentau", "", "sundew"], ["!", "", ""]] },
    "res_sw_hanne.3": { en: "The sundew has sticky red drops. A fly gets stuck on them.", t: [["Der", "", "the", "der"], ["Sonnentau", "", "sundew"], ["hat", "", "has", "haben"], ["klebrige", "", "sticky", "klebrig"], [",", "", ""], ["rote", "", "red", "rot"], ["Tropfen", "", "drops"], [".", "", ""], ["Eine", "", "a", "ein"], ["Fliege", "", "fly"], ["bleibt", "", "stays", "bleiben"], ["daran", "", "on them"], ["hängen", "", "stuck (hängen bleiben: get stuck)"], [".", "", ""]] },
    "res_sw_ludger.1": { en: "Hello! I'm Ludger, the roofer. I make roofs out of reed.", t: [["Hallo", "", "hello"], ["!", "", ""], ["Ich", "", "I", "ich"], ["bin", "", "am", "sein"], ["Ludger", "", "Ludger (name)"], [",", "", ""], ["der", "", "the"], ["Dachdecker", "", "roofer"], [".", "", ""], ["Ich", "", "I", "ich"], ["mache", "", "make", "machen"], ["Dächer", "", "roofs", "Dach"], ["aus", "", "out of"], ["Schilf", "", "reed"], [".", "", ""]] },
    "res_sw_ludger.2": { en: "We cut the reed in winter, when it's dry. A good thatched roof lasts fifty years!", t: [["Wir", "", "we", "wir"], ["schneiden", "", "cut"], ["das", "", "the", "der"], ["Schilf", "", "reed"], ["im", "", "in the", "in"], ["Winter", "", "winter"], [",", "", ""], ["wenn", "", "when"], ["es", "", "it"], ["trocken", "", "dry"], ["ist", "", "is", "sein"], [".", "", ""], ["Ein", "", "a", "ein"], ["gutes", "", "good", "gut"], ["Reetdach", "", "thatched roof"], ["hält", "", "lasts", "halten"], ["fünfzig", "", "fifty"], ["Jahre", "", "years", "Jahr"], ["!", "", ""]] },
    "res_sw_ludger.3": { en: "Under a thatched roof it's cool in summer and warm in winter.", t: [["Unter", "", "under"], ["einem", "", "a", "ein"], ["Reetdach", "", "thatched roof"], ["ist", "", "is", "sein"], ["es", "", "it"], ["im", "", "in the", "in"], ["Sommer", "", "summer"], ["kühl", "", "cool"], [",", "", ""], ["im", "", "in the", "in"], ["Winter", "", "winter"], ["warm", "", "warm"], [".", "", ""]] },
